-- AND THE BLAST RADIUS: how much does this licence hold altogether? A larger total means real ledger content sits alongside, and the predicate above is what you delete, never a broader one.
select (select count(*) from public.ledger_entries where license_hash = encode(digest('SB-TEST-2026','sha256'),'hex')) as entries_for_this_licence,
       (select count(*) from public.ledger_lines   where license_hash = encode(digest('SB-TEST-2026','sha256'),'hex')) as lines_for_this_licence;

delete from public.ledger_entries
 where license_hash = encode(digest('SB-TEST-2026', 'sha256'), 'hex')
   and entry_id = 'ZZ-PREVIEW-PROBE-20260930';

-- CONFIRM. Both must be 0. A delete that reports success and leaves the rows is what this step exists for.
select (select count(*) from public.ledger_entries where license_hash = encode(digest('SB-TEST-2026','sha256'),'hex') and entry_id = 'ZZ-PREVIEW-PROBE-20260930') as entries_remaining,
       (select count(*) from public.ledger_lines   where license_hash = encode(digest('SB-TEST-2026','sha256'),'hex') and entry_id = 'ZZ-PREVIEW-PROBE-20260930') as lines_remaining;
